import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../utils/AuthContext';
import { tournamentAPI } from '../utils/api';
import logo from '../Assets/logo.png';
import './styles/Tournament.css';

export default function HostTournamentPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [formData, setFormData] = useState({
    tournament_name: '',
    description: '',
    game_id: null,
    tournament_format: 'single_elimination',
    stage_type: 'single',
    max_players: 8,
    entry_fee: 0,
    start_date: '',
    start_time: '',
    url: '',
    tournament_fee_type: 'free',
    price_money: '',
    group_stage: '',
    final_stage: '',
    gamers_face: '',
    rank_by: '',
    group_participants: '',
    advanced_participants: '',
    registration_type: 'manual',
    gamer_tag: ''
  });
  const [tournamentStarted, setTournamentStarted] = useState(false);
  const [matches, setMatches] = useState([]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleCreateTournament = async () => {
    try {
      const response = await tournamentAPI.create(formData);
      alert('Tournament created successfully!');
      setFormData({
        tournament_name: '',
        description: '',
        game_id: null,
        tournament_format: 'single_elimination',
        stage_type: 'single',
        max_players: 8,
        entry_fee: 0,
        start_date: '',
        start_time: '',
        url: '',
        tournament_fee_type: 'free',
        price_money: '',
        group_stage: '',
        final_stage: '',
        gamers_face: '',
        rank_by: '',
        group_participants: '',
        advanced_participants: '',
        registration_type: 'manual',
        gamer_tag: ''
      });
    } catch (error) {
      console.error('Failed to create tournament:', error);
    }
  };

  const handleStartTournament = () => {
    setTournamentStarted(true);
    // Generate bracket/matches
    generateMatches();
  };

  const generateMatches = () => {
    // Simple bracket generation logic
    const m = [];
    for (let i = 0; i < formData.max_players / 2; i++) {
      m.push({
        id: i,
        player1: `Player ${i * 2 + 1}`,
        player2: `Player ${i * 2 + 2}`,
        winner: null
      });
    }
    setMatches(m);
  };

  return (
    <div className="host-tournament-page">
      <div className="host-topbar">
        <div className="host-brand">
          <img src={logo} alt="Gamelink logo" className="host-logo" />
        </div>
        <div className="host-tabs">
          <button type="button" onClick={() => navigate('/team-roster')}>Team Roster</button>
          <button type="button" onClick={() => navigate('/business-home')}>Home</button>
          <button type="button" onClick={() => navigate('/business-logs')}>Business logs & Ads</button>
        </div>
        <div className="host-avatar-wrapper">
          <div className="avatar-circle" />
        </div>
      </div>

      <div className="host-heading-row">
        <h1>Host: {user?.username || 'name'}</h1>
        <div className="host-badge">Tournament</div>
      </div>

      <div className="host-grid">
        <section className="host-panel">
          <div className="panel-title">Primary info</div>
          <div className="panel-section">
            <input
              type="text"
              name="tournament_name"
              placeholder="Tournament name"
              value={formData.tournament_name}
              onChange={handleChange}
            />
            <textarea
              name="description"
              placeholder="Description"
              value={formData.description}
              onChange={handleChange}
            />
            <div className="two-column-row">
              <input
                type="date"
                name="start_date"
                value={formData.start_date}
                onChange={handleChange}
              />
              <input
                type="time"
                name="start_time"
                value={formData.start_time}
                onChange={handleChange}
              />
            </div>
            <input
              type="text"
              name="url"
              placeholder="URL"
              value={formData.url}
              onChange={handleChange}
            />
            <div className="fee-toggle">
              <button
                type="button"
                className={formData.tournament_fee_type === 'free' ? 'active-toggle' : ''}
                onClick={() => setFormData({ ...formData, tournament_fee_type: 'free' })}
              >
                Free
              </button>
              <button
                type="button"
                className={formData.tournament_fee_type === 'paid' ? 'active-toggle' : ''}
                onClick={() => setFormData({ ...formData, tournament_fee_type: 'paid' })}
              >
                Paid
              </button>
            </div>
            <input
              type="text"
              name="price_money"
              placeholder="Price money"
              value={formData.price_money}
              onChange={handleChange}
            />
          </div>
        </section>

        <section className="host-panel">
          <div className="panel-title">Game info</div>
          <div className="panel-section">
            <input
              type="text"
              name="game_id"
              placeholder="Select game"
              value={formData.game_id || ''}
              onChange={handleChange}
            />
            <div className="radio-group">
              <label>
                <input
                  type="radio"
                  name="stage_type"
                  value="single"
                  checked={formData.stage_type === 'single'}
                  onChange={handleChange}
                />
                Single
              </label>
              <label>
                <input
                  type="radio"
                  name="stage_type"
                  value="double"
                  checked={formData.stage_type === 'double'}
                  onChange={handleChange}
                />
                Double
              </label>
            </div>
            <div className="subsection-title">Stage settings</div>
            <div className="two-column-row">
              <input
                type="text"
                name="group_stage"
                placeholder="Group stage"
                value={formData.group_stage}
                onChange={handleChange}
              />
              <input
                type="text"
                name="final_stage"
                placeholder="Final stage"
                value={formData.final_stage}
                onChange={handleChange}
              />
            </div>
            <div className="two-column-row">
              <input
                type="text"
                name="gamers_face"
                placeholder="Gamers face"
                value={formData.gamers_face}
                onChange={handleChange}
              />
              <input
                type="text"
                name="rank_by"
                placeholder="Rank by"
                value={formData.rank_by}
                onChange={handleChange}
              />
            </div>
            <div className="two-column-row">
              <input
                type="number"
                name="group_participants"
                placeholder="Group participants"
                value={formData.group_participants}
                onChange={handleChange}
              />
              <input
                type="number"
                name="advanced_participants"
                placeholder="Advanced participants"
                value={formData.advanced_participants}
                onChange={handleChange}
              />
            </div>
            <div className="format-options">
              <label>
                <input
                  type="radio"
                  name="tournament_format"
                  value="single_elimination"
                  checked={formData.tournament_format === 'single_elimination'}
                  onChange={handleChange}
                />
                Single Elimination
              </label>
              <label>
                <input
                  type="radio"
                  name="tournament_format"
                  value="double_elimination"
                  checked={formData.tournament_format === 'double_elimination'}
                  onChange={handleChange}
                />
                Double Elimination
              </label>
              <label>
                <input
                  type="radio"
                  name="tournament_format"
                  value="round_robin"
                  checked={formData.tournament_format === 'round_robin'}
                  onChange={handleChange}
                />
                Round Robin
              </label>
            </div>
          </div>
        </section>

        <section className="host-panel">
          <div className="panel-title">Registration</div>
          <div className="panel-section">
            <input
              type="number"
              name="max_players"
              placeholder="Max number of participants"
              value={formData.max_players}
              onChange={handleChange}
            />
            <div className="radio-group">
              <label>
                <input
                  type="radio"
                  name="registration_type"
                  value="manual"
                  checked={formData.registration_type === 'manual'}
                  onChange={handleChange}
                />
                Manual
              </label>
              <label>
                <input
                  type="radio"
                  name="registration_type"
                  value="sign_up"
                  checked={formData.registration_type === 'sign_up'}
                  onChange={handleChange}
                />
                Sign-up
              </label>
            </div>
            <button className="add-participants-button" type="button">+ Add Participants</button>
            <div className="gamer-tag-row">
              <input
                type="text"
                name="gamer_tag"
                placeholder="Gamer tag"
                value={formData.gamer_tag}
                onChange={handleChange}
              />
              <button className="submit-tag-button" type="button">Submit</button>
            </div>
            <div className="registered-list">
              <p className="registered-title">Registered participants:</p>
              <div className="registered-placeholder">No registered participants yet</div>
            </div>
            <button className="start-tournament-button" type="button" onClick={handleStartTournament}>Start tournament</button>
          </div>
        </section>
      </div>
    </div>
  );
}
